"""Launch once after completed zero-update preflight; never duplicate a live run."""
import pathlib,json,subprocess,sys,datetime,hashlib
R=pathlib.Path(__file__).resolve().parents[1];E=R/'execution';repo=R.parents[2];read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert not (E/'launch.json').exists()and not (R/'continue-10000/checkpoint.pt').exists()
a=read(E/'initial-development-preflight.json');b=read(E/'preflight-runtime.json');assert a['actualOptimizerUpdates']==b['preflightOptimizerUpdates']==0 and a['fullMixedViewDevelopmentExactlyMatchesParent']and b['allParametersFiniteNonzeroGradients']and b['originalGoldTargetsExactlyPreserved']and b['endEosCoefficient']==.3 and b['initialOtherObjectiveTermsExactlyMatchRound36']and b['onlyEligibleOriginalNewlineCeRemoved']and b['originalValidTargetDenominatorRetained'];assert read(E/'preflight-tests.json')['testsPassed']==37
assert read(E/'eos-full-training-mask-preflight.json')['allRowsMatchIndependentPositionCriterion']and read(E/'single-factor-audit.json')['trainerReversePatchExactlyEqualsControl']
for x in read(R/'source-manifest.json')['files']:assert sha(R/x['path'])==x['sha256']and (R/x['path']).stat().st_size==x['bytes'],x['path']
with (E/'controller.log').open('ab',buffering=0)as log:p=subprocess.Popen([sys.executable,str(E/'supervise.py')],cwd=repo,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
record=dict(pid=p.pid,utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),gitHead=subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip(),actualCompletedUpdatesAtLaunch=0,requestedUpdates=10000,policySha256=sha(R/'policy.json'),sourceManifestSha256=sha(R/'source-manifest.json'),initializationParent='round28',scientificComparator='round36',adoptionAnchor='round25',sourceCheckpointSha256=read(R/'policy.json')['parentCheckpointSha256'],changedLearningFactor='Exclude competing original newline main CE only at existing eligible human EOS positions; coefficient0.3 and original denominator fixed',detachedController=True,noPublicModelChange=True)
(E/'launch.json').write_text(json.dumps(record,indent=2)+'\n');waiters=[]
for script,name in [(R/'fixed-source-mrmp-dev/after_final.py','fixed-source'),(E/'wait_terminal_diagnostic.py','terminal-diagnostic'),(E/'wait_human_train_gap.py','human-train-gap'),(E/'complete_mechanical_assembly.py','full-assembly'),(E/'retain_paired_milestones.py','paired-milestone')]:
 with (E/(name+'-waiter.log')).open('ab',buffering=0)as log:w=subprocess.Popen([sys.executable,str(script)],cwd=repo,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
 waiters.append(dict(pid=w.pid,script=str(script.relative_to(R)),onlyReadOnlyDiagnosticsOrSnapshots=True))
(E/'final-diagnostic-launches.json').write_text(json.dumps(dict(utc=record['utc'],waiters=waiters,noTrainingUpdatesByWaiters=True),indent=2)+'\n');print(json.dumps(record))
